// ServerInterface represents all server handlers.
type ServerInterface interface {
	// This host's entire observed state, in one document
	// (GET /export)
	GetExport(w http.ResponseWriter, r *http.Request)
	// Liveness probe
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// Host facts and the running Boat version
	// (GET /host)
	GetHost(w http.ResponseWriter, r *http.Request)
	// Run one read-only host verb, without a journal record
	// (POST /host-reads/{verb})
	RunHostRead(w http.ResponseWriter, r *http.Request, verb string)
	// Run one host operation Atlas used to drive over SSH
	// (POST /host-verbs/{verb})
	RunHostVerb(w http.ResponseWriter, r *http.Request, verb string)
	// One operation's journal record
	// (GET /ops/{operation_id})
	GetOperation(w http.ResponseWriter, r *http.Request, operationId string)
	// Pause admission of new operations for a self-update
	// (POST /quiesce)
	Quiesce(w http.ResponseWriter, r *http.Request)
	// Resume admission of new operations after an aborted update
	// (POST /resume)
	Resume(w http.ResponseWriter, r *http.Request)
	// One supervised unit's liveness
	// (GET /units/{name})
	GetUnit(w http.ResponseWriter, r *http.Request, name UnitName)
	// Start or restart a supervised unit
	// (POST /units/{name})
	ActOnUnit(w http.ResponseWriter, r *http.Request, name UnitName)
	// Stage a signed release and launch a detached self-update
	// (POST /update)
	Update(w http.ResponseWriter, r *http.Request)
	// List every VM this host observes
	// (GET /vms)
	ListVirtualMachines(w http.ResponseWriter, r *http.Request)
	// Retract this VM's desired state
	// (DELETE /vms/{uuid})
	DeleteVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Observed state of one VM
	// (GET /vms/{uuid})
	GetVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Assert this VM's desired state
	// (PUT /vms/{uuid})
	PutVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid, params PutVirtualMachineParams)
	// Poll a migrating VM's hydration percent
	// (GET /vms/{uuid}/migrate/hydration)
	GetMigrationHydration(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid, params GetMigrationHydrationParams)
	// Run one mutating phase of a cross-host migration saga
	// (POST /vms/{uuid}/migrate/{phase})
	MigrateVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid, phase string)
	// Pause a running guest
	// (POST /vms/{uuid}/pause)
	PauseVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Rebuild a VM's root disk from an image or a snapshot
	// (POST /vms/{uuid}/rebuild)
	RebuildVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Attach or detach a Reserved IP's host-side 1:1 NAT
	// (POST /vms/{uuid}/reserved-ip)
	ReservedIpVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Resize a stopped VM
	// (POST /vms/{uuid}/resize)
	ResizeVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Resume a paused guest
	// (POST /vms/{uuid}/resume)
	ResumeVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Park a VM to free its RAM
	// (POST /vms/{uuid}/sleep)
	SleepVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Start a provisioned VM
	// (POST /vms/{uuid}/start)
	StartVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Stop a running VM
	// (POST /vms/{uuid}/stop)
	StopVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Destroy a VM and everything it holds on this host
	// (POST /vms/{uuid}/terminate)
	TerminateVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Wake a sleeping VM now
	// (POST /vms/{uuid}/wake)
	WakeVirtualMachine(w http.ResponseWriter, r *http.Request, uuid VirtualMachineUuid)
	// Stream observed changes as they happen
	// (GET /watch)
	Watch(w http.ResponseWriter, r *http.Request)
}

